<?php require '../config.php'; require_admin(); $error='';
if($_SERVER['REQUEST_METHOD']==='POST'){$name=trim($_POST['name']??'');if($name!==''){try{$s=$pdo->prepare("INSERT INTO categories(name) VALUES(?)");$s->execute([$name]);header('Location: categories.php');exit;}catch(PDOException $e){$error='Category name already exists or could not be saved.';}}}
if(isset($_GET['delete'])){$id=(int)$_GET['delete'];try{$s=$pdo->prepare("DELETE FROM categories WHERE id=?");$s->execute([$id]);header('Location: categories.php');exit;}catch(PDOException $e){$error='Cannot delete category while products use it.';}}
$rows=$pdo->query("SELECT c.id,c.name,COUNT(p.id) product_count FROM categories c LEFT JOIN products p ON p.category_id=c.id GROUP BY c.id,c.name ORDER BY c.id")->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><title>Categories</title><link rel="stylesheet" href="../assets/style.css"></head><body><main><h1>Manage Categories</h1><a href="index.php">Dashboard</a><p class="error"><?=h($error)?></p><form method="post"><label>New category<input name="name" required maxlength="100"></label><button>Add category</button></form><table><tr><th>ID</th><th>Name</th><th>Products</th><th>Action</th></tr><?php foreach($rows as $r):?><tr><td><?=$r['id']?></td><td><?=h($r['name'])?></td><td><?=$r['product_count']?></td><td><a href="category_edit.php?id=<?=$r['id']?>">Edit</a> · <a href="?delete=<?=$r['id']?>" onclick="return confirm('Delete category?')">Delete</a></td></tr><?php endforeach;?></table></main></body></html>